import { readFile, readdir, writeFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { hashPassword } from "better-auth/crypto";
import { getMigrations } from "better-auth/db/migration";
import type { Pool } from "pg";
import { createAuthentication } from "../src/lib/auth-config";
export async function migrate(pool: Pool) {
  // Core schema generated by the exact pinned Better Auth library, not a guessed auth schema.
  const auth = createAuthentication({
    pool,
    secret: "local-migration-only-not-an-authentication-key-0000",
    origin: "http://localhost:3002",
  });
  const migration = await getMigrations(auth.options);
  if (process.argv.includes("--write-schema"))
    await writeFile("migrations/001-better-auth.sql", await migration.compileMigrations());
  await migration.runMigrations();
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      "CREATE TABLE IF NOT EXISTS sounding_migration (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now())",
    );
    await client.query("SELECT pg_advisory_xact_lock(824701)");
    for (const name of (await readdir("migrations"))
      .filter((n) => /^00[2-9]-.*\.sql$/.test(n))
      .sort()) {
      const exists = await client.query("SELECT 1 FROM sounding_migration WHERE name=$1", [name]);
      if (!exists.rowCount) {
        await client.query(await readFile(`migrations/${name}`, "utf8"));
        await client.query("INSERT INTO sounding_migration(name) VALUES($1)", [name]);
      }
    }
    await client.query("COMMIT");
  } catch {
    await client.query("ROLLBACK");
    throw new Error("Database migration failed.");
  } finally {
    client.release();
  }
}
export async function seedDemo(pool: Pool, email: string, password: string) {
  if (password.length < 12)
    throw new Error("A demo password of at least 12 characters is required.");
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const existing = await client.query('SELECT id FROM "user" WHERE email=$1', [email]);
    if (!existing.rowCount) {
      const id = randomUUID(),
        account = randomUUID(),
        hashed = await hashPassword(password);
      await client.query(
        'INSERT INTO "user" (id,name,email,"emailVerified","createdAt","updatedAt") VALUES($1,$2,$3,true,now(),now())',
        [id, "Demo visitor", email],
      );
      await client.query(
        'INSERT INTO account (id,"accountId","providerId","userId",password,"createdAt","updatedAt") VALUES($1,$2,$3,$4,$5,now(),now())',
        [account, id, "credential", id, hashed],
      );
    }
    await client.query("COMMIT");
  } catch {
    await client.query("ROLLBACK");
    throw new Error("Demo account setup failed.");
  } finally {
    client.release();
  }
}
